+use anyhow::{Context, Result};
+use std::collections::HashMap;
+use std::path::Path;
+use tracing::{debug, info};
+
+use super::CheckpointMetadata;
+
+/// Result of checkpoint planning
+#[derive(Debug)]
+pub struct CheckpointPlan {
+    /// The new checkpoint metadata with files field populated
+    pub metadata: CheckpointMetadata,
+    /// Files that need to be uploaded to S3 (filename, local_full_path)
+    pub files_to_upload: Vec<(String, String)>,
+}
+
+/// Create a checkpoint plan with new metadata and list of files to upload
+pub fn plan_checkpoint(
+    local_checkpoint_dir: &Path,
+    new_checkpoint_id: String,
+    topic: String,
+    partition: i32,
+    sequence: u64,
+    consumer_offset: i64,
+    producer_offset: i64,
+    previous_metadata: Option<&CheckpointMetadata>,
+) -> Result<CheckpointPlan> {
+    let mut metadata = CheckpointMetadata::new(
+        new_checkpoint_id,
+        topic,
+        partition,
+        sequence,
+        consumer_offset,
+        producer_offset,
+    );
+
+    let mut files_to_upload = Vec::new();
+
+    // Collect all files in local checkpoint directory
+    let local_files = collect_local_files(local_checkpoint_dir)?;
+
+    info!(
+        "Found {} files in local checkpoint directory",
+        local_files.len()
+    );
+
+    // If no previous metadata, upload everything
+    let Some(prev_meta) = previous_metadata else {
+        info!("No previous checkpoint metadata - uploading all files");
+        for (filename, local_path) in local_files {
+            metadata.files.push(filename.clone());
+            files_to_upload.push((filename, local_path));
+        }
+        return Ok(CheckpointPlan {
+            metadata,
+            files_to_upload,
+        });
+    };
+
+    // Build map of filename -> file_path from previous checkpoint
+    let mut file_map: HashMap<String, String> = HashMap::new();
+    for file_path in &prev_meta.files {
+        // Extract just the filename from the path
+        let filename = file_path
+            .rsplit('/')
+            .next()
+            .unwrap_or(file_path)
+            .to_string();
+
+        file_map.insert(filename.clone(), file_path.clone());

comment:
**logic:** filename collision if different directories contain files with same name

If previous checkpoint has files in subdirectories (e.g., `sst/000001.sst` and `wal/000001.sst`), extracting just the filename creates a map key collision. Only the last file with that name would be kept in the map, causing incorrect deduplication logic.

```suggestion
    // Build map of filename -> file_path from previous checkpoint
    // Use full relative path as key to handle files with same name in different dirs
    let mut file_map: HashMap<String, String> = HashMap::new();
    for file_path in &prev_meta.files {
        // Extract the filename from the end of the path (handle both relative and absolute paths)
        let normalized_path = if file_path.starts_with("../") {
            // For relative references like "../2025-10-14T15-00-00Z/sst/000001.sst"
            // Extract everything after the checkpoint ID
            file_path.split('/').skip(2).collect::<Vec<_>>().join("/")
        } else {
            // For direct references, use as-is
            file_path.clone()
        };

        file_map.insert(normalized_path.clone(), file_path.clone());
    }
```

