+    // DOM-ish, window-ish, error objects, etc. — treat as leaf
+    if (
+        tag === '[object Window]' ||
+        tag === '[object Document]' ||
+        tag === '[object Element]' ||
+        tag === '[object Node]' ||
+        tag === '[object HTMLDocument]' ||
+        tag === '[object ShadowRoot]' ||
+        tag === '[object Error]'
