+        let payload = serde_json::to_string(&event)?;
+
+        let record = FutureRecord::to(topic).key(&key).payload(&payload);
+
+        producer
+            .send(record, Timeout::After(Duration::from_secs(5)))
+            .await
+            .map_err(|(e, _)| anyhow::anyhow!("Failed to send message: {e:?}"))?;
+    }
+
