```ts
type SelectableCardProps = {
    title: string
    description: ReactNode
    selected: boolean
    onClick: () => void
    className?: string
    'data-attr'?: string
} & (
    | { disabled: true; disabledReason: string }
    | { disabled?: false; disabledReason?: never }
)
```

so TS will catch these edge cases:

```ts
// disabled but no reason
<SelectableCard disabled={true} />

// not disabled but reason provided
<SelectableCard disabled={false} disabledReason="Some reason" />
