+function getGroupsSummaryQuery(groupTypeIndex: GroupTypeIndex, filters: GroupPropertyFilter[]): string {
+    let baseQuery = `SELECT count() as group_count, sum(toFloatOrDefault(JSONExtractString(properties, 'mrr'), 0.0)) as mrr_sum FROM groups WHERE index = ${groupTypeIndex}`
+
+    if (filters && filters.length > 0) {
