+                    const operator = 'operator' in filter ? filter.operator : 'exact'
+
+                    if (operator === 'exact' || !operator) {
+                        return `JSONExtractString(properties, '${key}') = '${value}'`
+                    } else if (operator === 'icontains') {
+                        return `positionCaseInsensitive(JSONExtractString(properties, '${key}'), '${value}') > 0`
+                    } else if (operator === 'is_set') {
+                        return `JSONHas(properties, '${key}')`
+                    } else if (operator === 'is_not_set') {
+                        return `NOT JSONHas(properties, '${key}')`
+                    }
+                }
+                return null
+            })
+            .filter(Boolean)
+
+        if (propertyConditions.length > 0) {
+            baseQuery += ` AND ${propertyConditions.join(' AND ')}`
+        }
+    }
+
+    return baseQuery
+}

